WITH src AS (SELECT * FROM suppliers WHERE city NOT IN ('New York', 'Bangkok') AND (city IS NULL OR city != 'Bangkok')), agg AS (SELECT CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND((100 * SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_us, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM src GROUP BY CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, pct_us FROM agg WHERE pct_us >= 56 ORDER BY rating_bucket DESC, pct_us DESC
